nodes=data['nodes']
edges=data['edges']
start=data['start']
dist={}
for node in nodes:
    dist=putmap(dist,node,-1)
dist=putmap(dist,start,0)
for step in range(len(nodes)):
    for edge in edges:
        u=edge['u']
        v=edge['v']
        w=edge['weight']
        if dist[u] != -1:
            candidate=dist[u]+w
            if dist[v] == -1 or candidate < dist[v]:
                dist=putmap(dist,v,candidate)
ordered=sorted(nodes)
main=[]
for node in ordered:
    main=main+[{'id':node,'distance':dist[node]}]
